#!/usr/bin/env node
/**
 * Shadow-mode selection comparator (LS-9661, AC4).
 *
 * detect-changes computes the LIVE selection (hand-maintained
 * e2e-surface-map.json) and, in shadow, the DERIVED selection (generated by
 * derive-surface-map.mjs) over the same changed-file list — both through
 * select-specs.mjs --json. This tool diffs the two results and emits:
 *
 *   - one greppable stdout line:  E2E-SELECT-SHADOW <compact json>
 *     (searchable across runs with ci_search_logs to measure the shadow
 *     period: escalation-rate delta and under-selection candidates)
 *   - optional Markdown for the job summary (--md-out)
 *
 * The verdict never fails the job — shadow mode is observe-only. The flip
 * decision (retiring the hand map) is gated on N days of these lines showing
 * no high-confidence under-selection, corroborated by the nightly LS-7850
 * auditor running against the derived map.
 *
 * Key fields:
 *   missingInDerived — specs the live map selected that the derived map did
 *     not (runAll expansions included). THE under-selection signal.
 *   extraInDerived   — specs only the derived map selected (over-selection;
 *     safe, costs minutes).
 *   escalation       — live vs derived full-suite promotion (>= promoteAt
 *     specs or an explicit runAll), the LS-8905 79% metric.
 *
 * Usage:
 *   node shadow-compare.mjs --live <select.json> --derived <select.json>
 *                           [--promote-at <n>] [--md-out <path>]
 */

import { readFileSync, writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

export function compareSelections({ live, derived, promoteAt = 100 }) {
  const liveSpecs = new Set(live.specs ?? []);
  const derivedSpecs = new Set(derived.specs ?? []);

  const liveFull = Boolean(live.runAll) || liveSpecs.size >= promoteAt;
  const derivedFull = Boolean(derived.runAll) || derivedSpecs.size >= promoteAt;

  // When a side escalates to the full suite it effectively selects every
  // spec, so spec-level diffs only matter for the non-escalated side(s).
  const missingInDerived = derivedFull
    ? []
    : [...liveSpecs].filter((s) => !derivedSpecs.has(s)).sort();
  const extraInDerived = liveFull
    ? []
    : [...derivedSpecs].filter((s) => !liveSpecs.has(s)).sort();

  return {
    live: {
      runAll: Boolean(live.runAll),
      count: liveSpecs.size,
      full: liveFull,
    },
    derived: {
      runAll: Boolean(derived.runAll),
      count: derivedSpecs.size,
      full: derivedFull,
    },
    escalation:
      liveFull === derivedFull
        ? 'same'
        : liveFull
          ? 'avoided-by-derived'
          : 'added-by-derived',
    missingInDerived,
    extraInDerived,
  };
}

export function renderMarkdown(result) {
  const lines = [];
  lines.push('### E2E selection shadow diff (LS-9661 — observe-only)');
  lines.push('');
  lines.push('| | live (hand map) | derived (graph) |');
  lines.push('|---|---|---|');
  lines.push(
    `| full suite | ${result.live.full ? '✅ yes' : 'no'} | ${result.derived.full ? '✅ yes' : 'no'} |`,
  );
  lines.push(
    `| selected specs | ${result.live.count} | ${result.derived.count} |`,
  );
  lines.push('');
  if (result.escalation === 'avoided-by-derived') {
    lines.push(
      '🎯 The derived map would have avoided this full-suite escalation (the LS-8905 79% metric).',
    );
  } else if (result.escalation === 'added-by-derived') {
    lines.push(
      'ℹ️ The derived map escalates where the hand map did not (over-selection — safe).',
    );
  }
  if (result.missingInDerived.length > 0) {
    lines.push('');
    lines.push(
      `⚠️ **${result.missingInDerived.length} spec(s) selected by the live map but NOT by the derived map** ` +
        '(potential under-selection — must be explained before the flip):',
    );
    for (const s of result.missingInDerived) lines.push(`- \`${s}\``);
  } else {
    lines.push('');
    lines.push('✅ Derived selection is a superset of the live selection.');
  }
  if (result.extraInDerived.length > 0) {
    lines.push('');
    lines.push(
      `${result.extraInDerived.length} spec(s) selected only by the derived map (over-selection, safe).`,
    );
  }
  lines.push('');
  return lines.join('\n') + '\n';
}

function parseArgs(argv) {
  const args = { live: null, derived: null, promoteAt: 100, mdOut: null };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--live') args.live = argv[++i];
    else if (a === '--derived') args.derived = argv[++i];
    else if (a === '--promote-at') args.promoteAt = Number(argv[++i]);
    else if (a === '--md-out') args.mdOut = argv[++i];
  }
  return args;
}

function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!args.live || !args.derived) {
    console.error('error: --live and --derived are required');
    process.exit(2);
  }
  const live = JSON.parse(readFileSync(args.live, 'utf8'));
  const derived = JSON.parse(readFileSync(args.derived, 'utf8'));
  const result = compareSelections({
    live,
    derived,
    promoteAt:
      Number.isFinite(args.promoteAt) && args.promoteAt > 0
        ? args.promoteAt
        : 100,
  });
  // Compact log line: full under-selection list (the signal that gates the
  // flip — usually short), but only counts + a sample for over-selection so
  // a 100-spec superset doesn't produce a kilobyte-long log line.
  const logLine = {
    ...result,
    missingInDerived: result.missingInDerived.slice(0, 25),
    missingInDerivedCount: result.missingInDerived.length,
    extraInDerived: result.extraInDerived.slice(0, 10),
    extraInDerivedCount: result.extraInDerived.length,
  };
  console.log(`E2E-SELECT-SHADOW ${JSON.stringify(logLine)}`);
  if (args.mdOut) writeFileSync(args.mdOut, renderMarkdown(result));
}

if (
  process.argv[1] &&
  import.meta.url === pathToFileURL(process.argv[1]).href
) {
  main();
}
